const sleep = ms => new Promise(r => setTimeout(r, ms));
const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => { const msg = JSON.parse(event.data); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } };
function call(method, params={}) { return new Promise(resolve => { const n=++id; pending.set(n,resolve); ws.send(JSON.stringify({id:n,method,params})); }); }
async function evalJS(expression) { const result=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true}); return result.result?.result?.value; }
await call('Page.enable'); await call('Runtime.enable');
await call('Page.navigate',{url:'http://127.0.0.1:5173/'});
await sleep(2500);
await evalJS("document.querySelector('#play-button').click()");
await sleep(2700);
const key = async (type, key, code) => call('Input.dispatchKeyEvent',{type,key,code,windowsVirtualKeyCode:code==='KeyW'?87:32});
await key('keyDown','w','KeyW');
let jumpState=false;
const start=Date.now(); let last=0;
while(Date.now()-start<80000){
  const elapsed=Date.now()-start;
  if(elapsed-last>=900){
    await key('keyDown',' ','Space'); await key('keyUp',' ','Space'); last=elapsed;
  }
  await sleep(250);
  if(elapsed%5000<250){
    const state=await evalJS("({progress:document.querySelector('#progress-fill').style.width,stage:document.querySelector('#stage-value').textContent,status:document.querySelector('#race-status').textContent,toast:document.querySelector('#toast').textContent,finished:!document.querySelector('#finish-screen').classList.contains('hidden'),banner:document.querySelector('#checkpoint-banner').textContent})");
    console.log(Math.round(elapsed/1000)+'s',JSON.stringify(state));
    if(state.finished) break;
  }
}
await key('keyUp','w','KeyW');
console.log('final',JSON.stringify(await evalJS("({progress:document.querySelector('#progress-fill').style.width,stage:document.querySelector('#stage-value').textContent,status:document.querySelector('#race-status').textContent,finished:!document.querySelector('#finish-screen').classList.contains('hidden')})")));
ws.close();

