const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = targets.find(t => t.type === 'page' && t.url.includes('localhost') || t.type === 'page' && t.url.includes('127.0.0.1:5173'));
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
ws.onmessage = e => { const m=JSON.parse(e.data); if(m.id && pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);} };
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
function send(method,params={}){return new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))})}
async function evalJS(expression){const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});return r.result?.result?.value}
async function key(type,code){await send('Input.dispatchKeyEvent',{type, key:code==='Space'?' ':code,code,windowsVirtualKeyCode:code==='Space'?32:code==='ArrowUp'?38:0})}
await send('Runtime.enable');
await evalJS("document.getElementById('play-button').click()");
await new Promise(r=>setTimeout(r,2900));
await key('keyDown','ArrowUp');
const started=Date.now(); let nextJump=Date.now(),nextLog=Date.now();
while(Date.now()-started<120000){
  if(Date.now()>=nextJump){await key('keyDown','Space');await key('keyUp','Space');nextJump=Date.now()+650}
  if(Date.now()>=nextLog){const state=await evalJS("({progress:document.getElementById('progress-fill').style.width,status:document.getElementById('race-status').textContent,stage:document.getElementById('stage-value').textContent,finish:!document.getElementById('finish-screen').classList.contains('hidden'),toast:document.getElementById('toast').textContent})");console.log(Math.round((Date.now()-started)/1000),state);if(state.finish)break;nextLog=Date.now()+2500}
  await new Promise(r=>setTimeout(r,80));
}
await key('keyUp','ArrowUp');
