const targets=await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page=targets.find(t=>t.type==='page'&&t.url==='http://127.0.0.1:5173/');
const version=await (await fetch('http://127.0.0.1:9222/json/version')).json();
const ws=new WebSocket(version.webSocketDebuggerUrl);let id=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};await new Promise(r=>ws.onopen=r);
const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
console.log(await send('Target.activateTarget',{targetId:page.id}));ws.close();

